#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26 02:30 — the scale re-analyses queue5 skipped (its session lookup read
# synth_<N>.log; the logs are synth_<N>_s1.log). No new runs: static -> map -> model -> extractor -> verify on the stored sessions.
# er50 / layered100 run at once, confined to CPUs 18,19 (off the synthetic app/observer cores of the family re-runs);
# er200 / ba500 wait for "FAMILY RERUN DONE" and run unconfined. Ends with "SCALE2 DONE" in synth_scale2.log (queue4 waits for it).
set -u; cd "$(dirname "$0")/.."
LD=$HOME/fish_traces/night_20261025_final; L=$LD/synth_scale2.log
log() { echo "[$(date +%T)] $*" | tee -a "$L"; }
log "scale2 driver start (pid $$)"
for pair in er50:synth_er_n50_s1:pin layered100:synth_layered_n100_s1:pin er200:synth_er_n200_s1:wait ba500:synth_ba_n500_s1:wait; do
  IFS=: read -r N NAME MODE <<< "$pair"; [ -f "$LD/STOP" ] && { log "STOP"; break; }
  S=$(grep -h "^\[synth\] session" "$LD/synth_${N}_s1.log" 2>/dev/null | tail -1 | awk '{print $3}'); [ -n "$S" ] || { log "$N: no session"; continue; }
  if [ "$MODE" = wait ]; then
    while ! grep -q "FAMILY RERUN DONE" "$LD/synth_loop2.log" 2>/dev/null; do sleep 30; done; CP=""
  elif grep -q "FAMILY RERUN DONE" "$LD/synth_loop2.log" 2>/dev/null; then CP=""; else CP=18,19; fi
  log "reanalyze $N $S (cpus ${CP:-all})"; T0=$SECONDS
  REANALYZE_CPUS=$CP bash tests/synth/reanalyze_synth.sh "tests/synth/generated/${N}_s1.json" "$S" > "$LD/reanalyze_$N.log" 2>&1 || log "  $N: reanalyze rc=$?"
  V=$HOME/fish_traces/synth_runs/verify_$NAME.txt
  log "  $N: $(grep -h VERDICT "$V" 2>/dev/null | tail -1) $(grep -h 'false positives' "$V" 2>/dev/null | tail -1 | cut -c1-110) ($((SECONDS - T0)) s)"
  grep -h -E '^  (join|sampled|trigger) +(MISSING|observed|candidate-listed|undersampled|inactive) ' "$V" 2>/dev/null | sed 's/^/      /' | tee -a "$L" >/dev/null
done
log "SCALE2 DONE"
